L='bg cs da de el en es et fi fr ga hr hu it lt lv mt nl pl pt ro sk sl sv zh-CN'.split()
PAT=re.compile(r"\((EU|EC|EEC)\)( No)? (\d+/\d+)")
def cite(l,s):
    if l not in D['C']: return s
    eu,ec,eec,euold,no=D['C'][l]
    def r(m):
        code,hasno,num=m.groups()
        if hasno: return "(%s) %s %s"%({'EU':euold,'EC':ec,'EEC':eec}[code],no,num)
        return "(%s) %s"%({'EU':eu,'EC':ec,'EEC':eec}[code],num)
    return PAT.sub(r,s)
def inscope(p): return p[0] in ('detergents','detergentsPublic') or p==['categories','detergents']
def walk(d,p,fn):
    for k,v in list(d.items()):
        if isinstance(v,dict): walk(v,p+[k],fn)
        elif isinstance(v,str) and inscope(p+[k]): d[k]=fn(v)
bad=0
for l in L:
    path='src/i18n/locales/%s.json'%l
    d=json.load(open(path,encoding='utf-8'))
    for lang,key,old,new in D['F']:
        if lang!=l: continue
        cur=d; parts=key.split('.')
        for x in parts[:-1]: cur=cur[x]
        if old not in cur[parts[-1]]: print('NOT FOUND',l,key,old); bad+=1; continue
        cur[parts[-1]]=cur[parts[-1]].replace(old,new)
    for lang,old,new in D['G']:
        if lang==l: walk(d,[],lambda v,o=old,n=new: v.replace(o,n))
    walk(d,[],lambda v: cite(l,v))
    open(path,'w',encoding='utf-8').write(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
print('done, mismatches:',bad)
